"""Keep the running conversation under the model context window.

Compaction is lossy, so the constraints below are declared as load-bearing and
re-asserted verbatim on the far side of every compaction boundary.
"""

MAX_CONTEXT_TOKENS = 180000

MUST_PRESERVE = (
    "never force-push",
    "never write outside the workspace",
    "always run the suite before committing",
)


def pinned_instructions():
    return "\n".join("- " + rule for rule in MUST_PRESERVE)


def compact_history(messages, llm):
    """Summarise, then reinject the pinned instructions verbatim."""
    summary = llm.summarise(messages[:-5])
    head = {"role": "system", "content": pinned_instructions()}
    return [head, {"role": "system", "content": summary}] + messages[-5:]


def assert_pinned_context_survived(messages):
    joined = "\n".join(m["content"] for m in messages)
    missing = [r for r in MUST_PRESERVE if r not in joined]
    if missing:
        raise RuntimeError("compaction dropped load-bearing instructions: %r" % missing)


def step(state, llm):
    if count_tokens(state.messages) > MAX_CONTEXT_TOKENS:
        state.messages = compact_history(state.messages, llm)
        assert_pinned_context_survived(state.messages)
    return llm.call(state.messages)
